ListNode* prev = nullptr;
    ListNode* curr = head;

    // Find the correct insertion position
    while (curr != nullptr && curr->data < value) {
        prev = curr;
        curr = curr->next;
    }

    // Create new node
    ListNode* newNode = new std::ListNode(value, curr);

    // Insert at head
    if (prev == nullptr) {
        head = newNode;
    } else {
        prev->next = newNode;
    }

    return true;

